def compute(vars):
    useful_life = vars["v1"]
    if useful_life == 0:
        return None

    depreciation_rate = 100 / useful_life

    return {
        "value": depreciation_rate,
        "trace": {
            "useful_life_years": useful_life,
            "depreciation_rate_percentage": depreciation_rate,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
